style.css:
@-moz-document domain("roblox.com") {
* {
        /* This creates the rainbow gradient */
        background: linear-gradient(to right, #ef5350, #f48fb1, #7e57c2, #2196f3, #26c6da, #43a047, #eeff41, #f9a825, #ff5722);
        
        /* This clips the background to only show through the text letters */
        -webkit-background-clip: text !important;
        background-clip: text !important;
        
        /* Makes the actual text transparent so the rainbow shows through */
        color: transparent !important;
        
        /* Animation settings */
        background-size: 200% auto !important;
        animation: rainbow_animation 5s linear infinite !important;
    }
}

/* The math for the movement */
@keyframes rainbow_animation {
    0% { background-position: 0% center; }
    100% { background-position: 200% center; }
}
